'use client';

import { useRef, useEffect, useState } from 'react';
import { PieChart } from 'lucide-react';
import { computeBreakdown, formatDurationSecs } from '@/lib/call-cost-utils';

interface Props {
  userCost: number;
  costDetails: unknown | null;
  durationMs?: number | null;
}

export function CallCostBreakdown({ userCost, costDetails, durationMs }: Props) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const details = costDetails as {
    product_costs?: Array<{ product?: string; cost?: number }>;
    combined_cost?: number;
    total_duration_seconds?: number;
  } | null;

  const breakdown = computeBreakdown(details, userCost);

  // Duration: prefer costDetails.total_duration_seconds, fall back to durationMs
  const durationSecs =
    details?.total_duration_seconds ??
    (durationMs != null ? Math.round(durationMs / 1000) : null);

  const durationLabel = formatDurationSecs(durationSecs);
  const durationMin = durationSecs ? (durationSecs / 60).toFixed(3) : null;
  const avgPerMin =
    durationSecs && durationSecs > 0
      ? `$${(userCost / (durationSecs / 60)).toFixed(4)}/min`
      : null;

  const mainItems  = breakdown.filter(b => !b.isAddon);
  const addonItems = breakdown.filter(b => b.isAddon);

  useEffect(() => {
    if (!open) return;
    function handleClick(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open]);

  return (
    <div ref={containerRef} className="relative inline-block">
      <button
        onClick={() => setOpen(v => !v)}
        className="text-gray-400 hover:text-[#004D3E] transition-colors"
        aria-label="Cost breakdown"
        title="Cost breakdown"
      >
        <PieChart size={13} />
      </button>

      {open && (
        <div className="absolute z-50 right-0 top-6 w-64 bg-white rounded-xl border border-gray-200 shadow-lg overflow-hidden">

          {/* Header */}
          <div className="px-4 pt-3 pb-2 border-b border-gray-100">
            <p className="text-[11px] font-medium text-gray-400 uppercase tracking-wide">Total cost</p>
            <p className="text-lg font-bold text-gray-900 mt-0.5">${userCost.toFixed(4)}</p>
          </div>

          {/* Duration stats */}
          {durationSecs != null && (
            <div className="px-4 py-2.5 border-b border-gray-100 grid grid-cols-2 gap-2">
              <div>
                <p className="text-[11px] text-gray-400">Call duration</p>
                <p className="text-xs font-semibold text-gray-700 mt-0.5">
                  {durationLabel}
                  {durationMin && <span className="font-normal text-gray-400"> ({durationMin} min)</span>}
                </p>
              </div>
              {avgPerMin && (
                <div>
                  <p className="text-[11px] text-gray-400">Average per minute</p>
                  <p className="text-xs font-semibold text-gray-700 mt-0.5">{avgPerMin}</p>
                </div>
              )}
            </div>
          )}

          {/* Components */}
          {mainItems.length > 0 && (
            <div className="px-4 py-2.5 border-b border-gray-100">
              <p className="text-[11px] font-semibold text-gray-500 mb-1.5">Components</p>
              <div className="space-y-1">
                {mainItems.map((item, i) => (
                  <div key={i} className="flex items-center justify-between">
                    <span className="text-xs text-gray-600">{item.name}</span>
                    <span className="text-xs font-medium text-gray-800 tabular-nums">
                      ${item.userCost.toFixed(4)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Add-ons */}
          {addonItems.length > 0 && (
            <div className="px-4 py-2.5 border-b border-gray-100">
              <p className="text-[11px] font-semibold text-gray-500 mb-1.5">Add-on</p>
              <div className="space-y-1">
                {addonItems.map((item, i) => (
                  <div key={i} className="flex items-center justify-between">
                    <span className="text-xs text-gray-600">{item.name}</span>
                    <span className="text-xs font-medium text-gray-800 tabular-nums">
                      ${item.userCost.toFixed(4)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* No breakdown available */}
          {breakdown.length === 0 && (
            <div className="px-4 py-3 border-b border-gray-100">
              <p className="text-xs text-gray-400">Detailed breakdown unavailable for this call.</p>
            </div>
          )}

          {/* Total footer */}
          <div className="px-4 py-2.5 bg-gray-50 flex items-center justify-between">
            <span className="text-xs font-semibold text-gray-700">Total</span>
            <span className="text-xs font-bold text-gray-900 tabular-nums">${userCost.toFixed(4)}</span>
          </div>
        </div>
      )}
    </div>
  );
}
